void (async function () {
  // x是采样员人数，y是志愿者人数
  const [x, y] = (await readline()).split(" ").map(Number);

  // x个采样员的正常效率
  const normals = (await readline()).split(" ").map(Number);

  // base 记录每个采样员的裸奔效率
  let base = 0;

  // add 记录每个采样员的递进新增效率
  const add = [];

  for (let normal of normals) {
    // M为采样效率浮动粒度
    const m = normal * 0.1;

    // 采样员正常效率是10M，如果没有志愿者协助组织，效率下降2M，即8M
    base += 8 * m;

