public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    // x是采样员人数，y是志愿者人数
    int x = sc.nextInt();
    int y = sc.nextInt();

    // x个采样员的正常效率
    int[] normals = new int[x];
    for (int i = 0; i < x; i++) normals[i] = sc.nextInt();

    // base 记录每个采样员的裸奔效率
    int base = 0;
    // increase 记录每个采样员的递进新增效率
    ArrayList<Integer> increase = new ArrayList<>();

    for (int normal : normals) {
      // M为采样效率浮动粒度
      int m = normal / 10;

      // 采样员正常效率是10M，如果没有志愿者协助组织，效率下降2M，即8M
      base += 8 * m;

      // 增加第1个采样员的新增效率
      increase.add(2 * m);
      // 增加第2个采样员的新增效率
      increase.add(m);
      // 增加第3个采样员的新增效率
      increase.add(m);
      // 增加第4个采样员的新增效率
      increase.add(m);
    }

    // 对所有新增效率降序
    increase.sort((a, b) -> b - a);

    // 裸奔效率 + 前y大的新增效率 就是 最高效率
    int ans =
        base
            + increase.subList(0, Math.min(y, increase.size())).stream()
                .reduce(Integer::sum)
                .orElse(0);
    System.out.println(ans);
  }
}

